using Flagman;
public static class AccessChecks
{
 public static int Run(){var s=new State();var now=DateTimeOffset.UtcNow;AccessService.Bootstrap(s,"test-manager-password");var manager=s.Users.Single(); WorkflowChecks.Check(AccessService.Login(s,"manager","test-manager-password")?.Id==manager.Id,"Bootstrap login"); WorkflowChecks.Check(AccessService.Login(s,"manager","wrong")==null,"Wrong password");var actor=new Actor(manager.Id,"manager");var supplier=AccessService.SaveAccount(s,null,new("supplier","Поставщик","supplier","supplier-password"),actor,now);try{AccessService.SaveAccount(s,null,new(" supplier ","Duplicate","supplier","supplier-password"),actor,now);throw new Exception("Whitespace login duplicate accepted");}catch(DomainException e){WorkflowChecks.Check(e.Status==409,"Unique normalized login");}var issued=AccessService.IssueKey(s,supplier.Id,actor,now);WorkflowChecks.Check(AccessService.Bearer(s,issued.Token)?.UserId==supplier.Id,"Bearer auth");AccessService.SaveAccount(s,supplier.Id,new("supplier","Поставщик","waiter",null),actor,now);WorkflowChecks.Check(AccessService.Bearer(s,issued.Token)==null,"Role invalidates key");try{AccessService.SaveAccount(s,manager.Id,new("manager","Менеджер","manager",null,false),actor,now);throw new Exception("Last manager disabled");}catch(DomainException e){WorkflowChecks.Check(e.Status==409,"Last manager guard");} Console.WriteLine("PASS Accounts_roles_revocation_last_manager");return 1;}
}
